boss_trace.go.src:
package main

import "fmt"

func main() {
	fuel := 10
	if fuel > 8 {
		fuel = fuel - 4
	}
	fmt.Println("a", fuel)
	if fuel > 8 {
		fuel = fuel - 4
	} else if fuel > 5 {
		fuel = fuel * 2
	}
	fmt.Println("b", fuel)
	switch {
	case fuel > 10:
		fuel = fuel - 10
		fallthrough
	case fuel > 100:
		fuel = fuel + 1
	}
	fmt.Println("c", fuel)
	if f := fuel * 3; f > 9 && fuel != 3 {
		fuel = f
	}
	fmt.Println("d", fuel)
}

