package main

import "fmt"

// isOpen walks to the door to check. It tells you every time it runs.
func isOpen() bool {
	fmt.Println("  (walked to the door)")
	return true
}

func main() {
	hasParcel := false
	fmt.Println("Trip 1, no parcel:")
	fmt.Println("  deliver?", hasParcel && isOpen())
	hasParcel = true
	fmt.Println("Trip 2, with a parcel:")
	fmt.Println("  deliver?", hasParcel && isOpen())
}

